/// <summary>
/// The <c>AVAWHSControlCoilInsideDiameter</c> class is responsible for handling the coil inside Diameter
/// </summary>
#AVAWHSRF
[
    WhsControlFactory(#AVACoilInsideDiameter)
]
public class AVAWHSControlCoilInsideDiameter extends WhsControl
{
}

Method.Source:
public boolean process()
{
    if (this.parmData())
    {
        fieldValues.insert(#AVACoilInsideDiameter, this.parmData());
    }
    return super();
}

public boolean canProcessDefaultValue()
{
    if (this.parmData())
    {
        return true;
    }

    return false;
}
